CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,password TEXT NOT NULL,recovery_hash TEXT NOT NULL,publisher INTEGER NOT NULL DEFAULT 0,disabled INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS session_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS rates(key TEXT NOT NULL,bucket INTEGER NOT NULL,hits INTEGER NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(key,bucket));
CREATE TABLE IF NOT EXISTS blobs(hash TEXT PRIMARY KEY,bytes INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_blobs(user_id TEXT NOT NULL REFERENCES users(id),hash TEXT NOT NULL REFERENCES blobs(hash),PRIMARY KEY(user_id,hash));
CREATE TABLE IF NOT EXISTS pack_ids(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS releases(pack_id TEXT NOT NULL REFERENCES pack_ids(id),version TEXT NOT NULL,owner TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL,pack_lock TEXT UNIQUE NOT NULL,manifest TEXT NOT NULL,created INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(pack_id,version));
CREATE TABLE IF NOT EXISTS release_files(pack_id TEXT NOT NULL,version TEXT NOT NULL,hash TEXT NOT NULL REFERENCES blobs(hash),PRIMARY KEY(pack_id,version,hash),FOREIGN KEY(pack_id,version) REFERENCES releases(pack_id,version));
CREATE TABLE IF NOT EXISTS friends(sender TEXT NOT NULL REFERENCES users(id),recipient TEXT NOT NULL REFERENCES users(id),accepted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(sender,recipient));
CREATE TABLE IF NOT EXISTS blocks(owner TEXT NOT NULL REFERENCES users(id),target TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(owner,target));
CREATE TABLE IF NOT EXISTS lobbies(id TEXT PRIMARY KEY,host TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,pack_id TEXT NOT NULL,pack_version TEXT NOT NULL,visibility TEXT NOT NULL,capacity INTEGER NOT NULL,revision INTEGER NOT NULL,invite_hash TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,FOREIGN KEY(pack_id,pack_version) REFERENCES releases(pack_id,version));
CREATE INDEX IF NOT EXISTS lobby_expiry ON lobbies(expires);
CREATE TABLE IF NOT EXISTS members(lobby TEXT NOT NULL REFERENCES lobbies(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),edition TEXT NOT NULL,build TEXT NOT NULL,pack_lock TEXT NOT NULL,ready INTEGER NOT NULL DEFAULT 0,joined INTEGER NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(lobby,user_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(id),pack_id TEXT NOT NULL,version TEXT NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL);
